import RPi.GPIO as GPIO
import time
import sys

# Configuration
GAS_SENSOR_PIN = 16          # BCM GPIO 16 (physical pin 11)
WARNING_LED_PIN = 12          # BCM GPIO 12 (physical pin 11)
LOW_THRESHOLD = 0.5           # seconds between consecutive LOW readings
ALARM_COUNT = 3
ALARM_FLASH_DURATION = 0.2    # seconds per flash
ALARM_FLASH_COUNT = 3
ALARM_FLASH_ON = 200          # milliseconds
ALARM_FLASH_OFF = 200         # milliseconds

def setup_gpio():
    """Configure GPIO pins for input and output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GAS_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(WARNING_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error setting up GPIO: {e}", file=sys.stderr)
        sys.exit(1)

def cleanup_gpio():
    """Safely clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}", file=sys.stderr)

def check_gas_sensor():
    """Read the digital gas sensor and return True if LOW, False otherwise."""
    try:
        return GPIO.input(GAS_SENSOR_PIN) == GPIO.LOW
    except Exception as e:
        print(f"Error reading gas sensor: {e}", file=sys.stderr)
        return False

def trigger_warning():
    """Flash the warning LED three times."""
    try:
        for _ in range(ALARM_FLASH_COUNT):
            GPIO.output(WARNING_LED_PIN, GPIO.HIGH)
            time.sleep(ALARM_FLASH_ON)
            GPIO.output(WARNING_LED_PIN, GPIO.LOW)
            time.sleep(ALARM_FLASH_OFF)
    except Exception as e:
        print(f"Error during warning flash: {e}", file=sys.stderr)

def check_gas_threshold():
    """Count consecutive LOW readings and trigger an alarm if three consecutive LOW."""
    count = 0
    while not check_gas_sensor():
        count += 1
        if count >= LOW_THRESHOLD:
            trigger_warning()
            return True
    return False

def main():
    """Main loop: continuously sample the gas sensor and trigger alarms."""
    setup_gpio()
    print("Gas sensor monitoring started. Press Ctrl+C to exit.")
    try:
        while True:
            if check_gas_threshold():
                print("Gas level detected. Warning!")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("\nMonitoring stopped by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

