def setup_camera(resolution=(640, 480), exposure_mode='auto', image_effect='none',
                 brightness=50, contrast=0):
    """
    Sets up the Raspberry Pi Camera Module using the Raspberry Pi Camera Driver API.

    Args:
        resolution: Camera resolution tuple (width, height).
        exposure_mode: Camera exposure mode.
        image_effect: Camera image effect.
        brightness: Camera brightness.
        contrast: Camera contrast.

    Returns:
        Camera object.
    """
    try:
        from picamera2 import Picamera2
        from picamera2.encoders import MJPEGEncoder
        from picamera2.outputs import FileOutput

        # Initialize Picamera2
        picam2 = Picamera2()

        # Configure camera settings
        config = picam2.create_preview_configuration(
            main={"size": resolution, "format": "RGB888"},
            controls={"ExposureMode": exposure_mode, "Brightness": brightness, "Contrast": contrast}
        )
        picam2.configure(config)

        # Set image effect
        picam2.set_controls({"ImageEffect": image_effect})

        # Set output
        output = FileOutput('/home/pi/plant_images/plant_image.jpg')
        picam2.start_recording(output)

        logging.info("Camera initialized successfully.")
        return picam2

    except Exception as e:
        logging.error(f"Error setting up camera: {e}")
        return None

def capture_image(picam2):
    """
    Captures an image from the camera and saves it to disk.

    Args:
        picam2: Camera object.

    Returns:
        Path to the saved image file.
    """
    try:
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"plant_image_{timestamp}.jpg"

        # Capture image
        picam2.capture_file(filename)

        logging.info(f"Image captured and saved to {filename}")
        return filename

