import signal
import sys
import time
import serial

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
LOG_FILE = "distance_log.txt"
SLEEP_INTERVAL = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def open_serial_port(port, baudrate, timeout):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
            write_timeout=timeout,
        )
        if not ser.is_open:
            print(f"Error: serial port {port} not opened.", file=sys.stderr)
            return None
        print(f"Opened {port} @ {baudrate} baud.")
        return ser
    except serial.SerialException as exc:
        print(f"Error opening serial port {port}: {exc}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"Unexpected error opening {port}: {exc}", file=sys.stderr)
        return None


def read_distance(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error reading from serial port: {exc}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"Unexpected error reading from serial port: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        line = raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        print(f"Error decoding line: {exc}", file=sys.stderr)
        return None

    if not line:
        return None

    try:
        distance_cm = float(line)
    except ValueError:
        print(f"Warning: malformed data received (not a float): '{line}'", file=sys.stderr)
        return None

    return distance_cm


def log_distance(ser, distance_cm):
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp},distance_cm{distance_cm:.2f}\n"
    try:
        ser.write(log_entry.encode("ascii"))
        ser.flush()
    except serial.SerialException as exc:
        print(f"Error writing to log file: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error writing to log file: {exc}", file=sys.stderr)


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = open_serial_port(SERIAL_PORT, BAUD_RATE, 0.1)
    if ser is None:
        print("Exiting due to serial port error.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            distance = read_distance(ser)
            if distance is not None:
                log_distance(ser, distance)
            time.sleep(SLEEP_INTERVAL)
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

