    _running = False


def _get_camera_number(device_path: str) -> int:
    try:
        return int(device_path.split("/")[-1].split("_")[0])
    except ValueError:
        logger.error("Invalid camera device path: %s", device_path)
        return -1


def _get_resolution(device_path: str) -> tuple:
    try:
        cap = cv2.VideoCapture(device_path)
        if not cap.isOpened():
            logger.error("Could not open camera at %s", device_path)
            return None, None
        width, height = cap.get(cv2.CAP_PROP_FRAME_WIDTH), cap.get(cv2.CAP_PROP_FRAME_HEIGHT)
        cap.release()
        return width, height
    except Exception as e:
        logger.error("Error reading camera resolution from %s: %s", device_path, e)
        return None, None


def _get_motion_threshold(device_path: str) -> int:
    try:
        cap = cv2.VideoCapture(device_path)
        if not cap.isOpened():
            logger.error("Could not open camera at %s", device_path)
            return DEFAULT_MOTION_THRESHOLD
        ret, frame = cap.read()
        if not ret or frame is None:
            logger.error("Could not read frame from camera at %s", device_path)
