import asyncio
import logging
import os
import signal
import sys
import time
from datetime import datetime

from gpiozero import MotionSensor
from gpiozero.exc import GPIOZeroError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

PIR_PIN = 17
IMAGE_DIR = "images"
LOG_FILE = "security.log"
DEBOUNCE_TIME = 0.5
NUM_BACKUPS = 7

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


def _log_motion(message):
    logger.info(message)


def _capture_image(sensor):
    image_dir = os.path.join(IMAGE_DIR, datetime.now().strftime("%Y%m%d_%H%M%S"))
    try:
        os.makedirs(image_dir, exist_ok=True)
        filename = os.path.join(image_dir, f"motion_{datetime.now().strftime('%Y%m%d_%H%M%S')}.jpg")
        with open(filename, "wb") as fh:
            fh.write(sensor.value)
        logger.info("Image captured: %s", filename)
    except OSError as exc:
        logger.error("Failed to capture image: %s", exc)
    except Exception as exc:
        logger.error("Unexpected error capturing image: %s", exc)


def _write_to_log(message):
    try:
        with open(LOG_FILE, "a") as fh:
            fh.write(message + "\n")
    except OSError as exc:
        logger.error("Failed to write to log file: %s", exc)
    except Exception as exc:
        logger.error("Unexpected error writing to log: %s", exc)


def _read_last_five_logs(queue):
    try:
        for _ in range(NUM_BACKUPS):
            if not _running:
                break
            try:
                entry = queue.get(timeout=1)
                logger.info("Last five log entries: %s", entry)
            except asyncio.QueueEmpty:
                break
    except Exception as exc:
        logger.error("Error reading last five logs: %s", exc)


def _process_motion_event(sensor, queue):
    try:
        if sensor.value:
            _log_motion("Motion detected by PIR sensor")
            _capture_image(sensor)
            _write_to_log("Motion detected by PIR sensor")
            logger.info("Motion detected by PIR sensor")
    except Exception as exc:
        logger.error("Error processing motion event: %s", exc)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        sensor = MotionSensor(PIR_PIN, pull_up=False, bounce_time=DEBOUNCE_TIME)
    except GPIOZeroError as exc:
        logger.error("Failed to initialize GPIO: %s", exc)
        sys.exit(1)
    except Exception as exc:
        logger.error("Unexpected error initializing GPIO: %s", exc)
        sys.exit(1)

    try:
        queue = asyncio.Queue()
    except Exception as exc:
        logger.error("Failed to create queue: %s", exc)
        sensor.close()
        sys.exit(1)

    try:
        async def consumer():
            while _running:
                try:
                    motion_detected = queue.get(timeout=1)
                    logger.info("Motion detected by PIR sensor")
                    _process_motion_event(sensor, queue)
                except asyncio.QueueEmpty:
                    continue
                except Exception as exc:
                    logger.error("Error in consumer loop: %s", exc)
                    break
        consumer_task = asyncio.create_task(consumer())
    except Exception as exc:
        logger.error("Failed to start consumer task: %s", exc)
    finally:
        try:
            sensor.close()
        except Exception:
            pass
        try:
            queue.put(None)
        except asyncio.QueueFull:
            pass
        try:
            os.remove(LOG_FILE)
        except OSError:
            pass
        try:
            os.rmdir(IMAGE_DIR)
        except OSError:
            pass
        logger.info("Application stopped.")


if __name__ == "__main__":
    main()

