#!/usr/bin/env python3
"""
PIR-based occupancy monitor for Raspberry Pi.

Wiring (40-pin header):
  PIR1 (zone 1)  -> GPIO17 (physical 11)
  PIR2 (zone 2)  -> GPIO27 (physical 13)
  PIR3 (zone 3)  -> GPIO22 (physical 15)
  I2C1 SDA -> GPIO2 (physical 3)
  I2C1 SCL -> GPIO3 (physical 5)

The VL53L0X is a time-of-flight sensor on I2C1 bus.
"""

import signal
import sys
import time
import logging
from collections import deque

import board
import busio
import adafruit_vl53l0x

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
PIR_ZONES = {
    1: board.D17,
    2: board.D27,
    3: board.D22,
}

I2C_BUS = 1
I2C_ADDR = 0x1F

VALID_DISTANCE_THRESHOLD = 1000.0  # meters
MOVING_AVERAGE_WINDOW = 5
MOVING_AVERAGE_DELAY = 0.1         # seconds

LOG_FILE = "occupancy.log"

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_sensor = None
_i2c = None
_log = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _sensor, _i2c, _log
    if _sensor is not None:
        try:
            _sensor.stop()
        except Exception:
            pass
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
    if _log is not None:
        try:
            _log.flush()
            _log.close()
        except Exception:
            pass


def _init_sensor():
    global _sensor, _i2c, _log
    try:
        _i2c = busio.I2C(board.SCL, board.SDA)
        _sensor = adafruit_vl53l0x.VL53L0X(_i2c)
        _sensor.start()
        logging.info("VL53L0X sensor initialized on I2C bus %d", I2C_BUS)
    except Exception as exc:
        logging.error("Failed to initialize VL53L0X sensor: %s", exc)
        raise


def _init_logging():
    global _log
    try:
        _log = logging.getLogger("occupancy")
        _log.setLevel(logging.INFO)
        _log.handlers.clear()
        _log.formatters.clear()
        _log.addHandler(logging.StreamHandler(sys.stdout))
        _log.addHandler(logging.FileHandler(LOG_FILE))
        _log.info("Logging started at %s", LOG_FILE)
    except Exception as exc:
        logging.error("Failed to initialize logging: %s", exc)
        raise


def _validate_distance(distance):
    if distance <= 0:
        logging.warning("Distance %s is invalid (distance <= 0)", distance)
        return False
    return distance < VALID_DISTANCE_THRESHOLD


def _read_distance(zone):
    if _sensor is None:
        logging.warning("VL53L0X sensor not initialized for zone %d", zone)
        return None
    try:
        return _sensor.range
    except Exception as exc:
        logging.error("Error reading distance from VL53L0X: %s", exc)
        return None


def _read_all_distances():
    distances = deque(maxlen=MOVING_AVERAGE_WINDOW)
    for zone in PIR_ZONES:
        raw = _read_distance(zone)
        if raw is not None:
            distances.append(raw)
            if len(distances) > MOVING_AVERAGE_WINDOW:
                distances.popleft()
    return list(distances)


def _validate_readings(readings):
    if not readings:
        logging.warning("No valid distance readings from VL53L0X")
        return False
    if not all(
        _validate_distance(raw)
        for raw in readings
    ):
        logging.warning("Invalid distance readings: %s", readings)
        return False
    return True


def _process_readings(readings):
    if not readings:
        return False
    if not all(
        _validate_distance(raw)
        for raw in readings
    ):
        logging.warning("Invalid distance readings: %s", readings)
        return False
    return True


def _log_event(zone, distance, is_valid):
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    message = (
        f"{timestamp} - Zone {zone} - "
        f"Raw: {distance:.2f}m - Valid: {is_valid}"
    )
    logging.info(message)


def _stop_callbacks(signum=None, frame=None):
    global _running
    _running = False


def main():
    global _running, _sensor, _i2c, _log

    signal.signal(signal.SIGTERM, _stop_callbacks)

    _init_sensor()
    _init_logging()

    try:
        _sensor = adafruit_vl53l0x.VL53L0X(_i2c)
        _sensor.start()
    except Exception as exc:
        logging.error("Failed to initialize VL53L0X sensor: %s", exc)
        _sensor = None

    try:
        while _running:
            readings = _read_all_distances()
            is_valid = _process_readings(readings)
            if is_valid:
                _log_event(1, readings[0], True)
            else:
                _log_event(1, readings[0], False)
            time.sleep(MOVING_AVERAGE_DELAY)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

