import os
import time
import signal
import sys
import numpy as np
from PIL import Image

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera():
    """Initializes the Pi Camera Module via the Pi Camera Interface (Pi CI) via the CSI bus."""
    try:
        from picamera2 import Picamera2
        picam2 = Picamera2()
        # Configure for a standard 4:3 aspect ratio
        config = picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"}
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(2.0)  # Allow camera to warm up
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def run_background_subtraction(picam2, delta=5, min_size=5000, min_frames=8):
    """Runs background subtraction on the Pi Camera and returns the motion-detected image."""
    try:
        # Capture a frame
        frame = picam2.capture_array()
        if frame is None:
            raise RuntimeError("Failed to capture frame")

        # Convert to grayscale
        gray = np.asarray(Image.fromarray(frame).convert("L"))

        # Running weighted-average background model
        background = np.zeros_like(gray)
        for i in range(gray.shape[0]):
            for j in range(gray.shape[1]):
                # Calculate the difference between the current frame and the background
                diff = gray[i, j] - background[i, j]
                # Apply a delta threshold to detect motion
                if np.abs(diff) > delta:
                    background[i, j] += diff
                    background[i, j] /= min_frames
                    if background[i, j] > min_size:
                        motion_mask = np.zeros_like(gray)
                        motion_mask[i, j] = 1
                        return Image.fromarray(motion_mask)

        return Image.fromarray(background)

    except Exception as e:
        print(f"Error during background subtraction: {e}", file=sys.stderr)
        return None

def save_motion_images(motion_image, save_dir):
    """Saves the motion image to a directory."""
    try:
        os.makedirs(save_dir, exist_ok=True)
        filename = os.path.join(save_dir, f"motion_{time.time()}.png")
        motion_image.save(filename)
        print(f"Motion image saved to {filename}")
    except Exception as e:
        print(f"Error saving motion image: {e}", file=sys.stderr)

def main():
    """Main function to run the motion detection and save images."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    try:
        # Throttle saves to no more than one every 30 seconds
        save_interval = 30
        last_save_time = 0.0
        while _running:
            motion_image = run_background_subtraction(picam2)
            if motion_image is not None:
                save_motion_images(motion_image, "./saved_imgs")
                last_save_time = time.time()

                # Check if enough frames have been detected
                if (time.time() - last_save_time) >= save_interval:
                    save_motion_images(motion_image, "./saved_imgs")
                    last_save_time = time.time()

            # Wait for the next frame
            time.sleep(0.1)

    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        # Release the camera
        if picam2 is not None:
            try:
                picam2.stop()
                picam2.close()
                print("Camera released.")
            except Exception as e:
                print(f"Error releasing camera: {e}", file=sys.stderr)

if __name__ == "__main__":
    main()

