import os
import sys
import time
import signal
import logging
import numpy as np
import torch
from torchvision import transforms, models
from PIL import Image

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

IMAGE_DIR = "images"
MODEL_PATH = "resnet50_v2.pth"

_running = True

def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False

def _ensure_dir(path):
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as exc:
        logger.error("Cannot create directory %s: %s", path, exc)
        raise

def _download_pretrained(model_path, download_dir):
    try:
        if not os.path.exists(download_dir):
            os.makedirs(download_dir)
        if not os.path.exists(model_path):
            logger.info("Downloading %s", model_path)
            torch.hub.download_url_to_file(model_path, download_dir)
        logger.info("Model downloaded to %s", download_dir)
    except Exception as exc:
        logger.error("Error downloading model: %s", exc)
        raise

def _load_pretrained(model_path, download_dir):
    try:
        if not os.path.exists(model_path):
            logger.info("Downloading %s", model_path)
            torch.hub.download_url_to_file(model_path, download_dir)
        if not os.path.exists(model_path):
            logger.error("Model not found after download.")
            raise FileNotFoundError(f"Model not found after download.")
        logger.info("Model loaded from %s", download_dir)
        return models.resnet50_v2(pretrained=True, num_classes=1000)
    except Exception as exc:
        logger.error("Error loading model: %s", exc)
        raise

def _preprocess_image(image_path, transform=None):
    try:
        if transform is None:
            transform = transforms.Compose([
                transforms.Resize((224, 224)),
                transforms.CenterCrop(224),
                transforms.ToTensor(),
                transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]),
            ])
        return transform(Image.open(image_path))
    except Exception as exc:
        logger.error("Error preprocessing image: %s", exc)
        raise

def _predict_image(model, image_path):
    try:
        image = _preprocess_image(image_path)
        image = image.unsqueeze(0)
        with torch.no_grad():
            output = model(image)
        return output.softmax(dim=1)[0].tolist()
    except Exception as exc:
        logger.error("Error during prediction: %s", exc)
        raise

def _cleanup():
    try:
        if os.path.exists(IMAGE_DIR):
            os.rmdir(IMAGE_DIR)
        logger.info("Image directory cleaned up.")
    except Exception as exc:
        logger.error("Error cleaning up image directory: %s", exc)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _ensure_dir(IMAGE_DIR)
    except OSError as exc:
        logger.error("Cannot create image directory: %s", exc)
        sys.exit(1)

    try:
        _download_pretrained(MODEL_PATH, IMAGE_DIR)
    except Exception as exc:
        logger.error("Failed to download pretrained model: %s", exc)
        sys.exit(1)

    try:
        model = _load_pretrained(MODEL_PATH, IMAGE_DIR)
    except Exception as exc:
        logger.error("Failed to load pretrained model: %s", exc)
        sys.exit(1)

    try:
        _ensure_dir(IMAGE_DIR)
    except OSError as exc:
        logger.error("Cannot create image directory: %s", exc)
        sys.exit(1)

    try:
        image_path = os.path.join(IMAGE_DIR, f"images/{time.strftime('%Y%m%d_%H%M%S')}.jpg")
        if not os.path.exists(image_path):
            logger.info("Capturing image...")
            try:
                from PIL import Image
                image = Image.open("camera.jpg").convert("RGB")
                image.save(image_path)
                logger.info("Image saved to %s", image_path)
            except Exception as exc:
                logger.error("Failed to capture image: %s", exc)
                sys.exit(1)
        else:
            logger.info("Image already exists: %s", image_path)

        try:
            image = Image.open(image_path).convert("RGB")
            image = image.resize((224, 224))
            image = image.crop(224).convert("RGB")
            image = image.resize((256, 256))
            image = image.convert("HWC")
            image = image.float()
            image = (image - 0.485) / 0.229
            image = (image - 0.456) / 0.224
            image = (image - 0.406) / 0.225
            logger.info("Image preprocessed: %s", image_path)
        except Exception as exc:
            logger.error("Failed to preprocess image: %s", exc)
            sys.exit(1)

        try:
            predictions = _predict_image(model, image_path)
            logger.info("Predictions: %s", predictions)
        except Exception as exc:
            logger.error("Failed to make predictions: %s", exc)
            sys.exit(1)

    except Exception as exc:
        logger.error("Unexpected error: %s", exc)
        sys.exit(1)
    finally:
        _cleanup()

if __name__ == "__main__":
    main()

