import signal
import sys
import time
import logging

import numpy as np
import cv2
import soundfile as sf
from scipy.io.wavfile import read

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DOOR_ACTUATOR_PIN = 18
BUTTON_PIN = 17
SOUND_WAVES = {
    "welcome": "welcome.wav",
    "wait": "wait.wav",
    "later": "later.wav",
}

TRAINING_FILE = "eigenfaces.dat"
POSITIVE_LABEL = "positive"
POSITIVE_THRESHOLD = 0.5

SOUND_FREQUENCY = 48000
SOUND_DURATION = 0.5

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
door = None
button = None
mixer = None
face_recognizer = None

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received – shutting down.", signum)
    _running = False


def load_eigenfaces():
    """Load the EigenFaceRecognizer model from the training file."""
    global face_recognizer
    try:
        if not os.path.exists(TRAINING_FILE):
            raise FileNotFoundError(f"Training file not found: {TRAINING_FILE}")
        logger.info("Loading EigenFaceRecognizer model from %s.", TRAINING_FILE)
        face_recognizer = cv2.face.EigenFaceRecognizer_create()
        face_recognizer.read(TRAINING_FILE)
        logger.info("EigenFaceRecognizer model loaded.")
        return face_recognizer
    except Exception as exc:
        logger.error("Failed to load EigenFaceRecognizer: %s", exc)
        raise


def initialize_sound_mixer():
    """Initialize the sound mixer at 48000 Hz."""
    global mixer
    try:
        logger.info("Initializing sound mixer at %d Hz.", SOUND_FREQUENCY)
        mixer = sf.Sound(SOUND_WAVES["welcome"], SOUND_FREQUENCY)
        mixer.play()
        return mixer
    except Exception as exc:
        logger.error("Failed to initialize sound mixer: %s", exc)
        raise


def initialize_door_lock():
    """Initialize the door actuator on GPIO18 (active-high)."""
    global door
    try:
        logger.info("Initializing door lock on GPIO18 (active-high).")
        door = OutputDevice(DOOR_ACTUATOR_PIN, active_high=True, initial_value=False)
        logger.info("Door lock initialized on GPIO18.")
        return door
    except GPIOZeroError as exc:
        logger.error("Failed to initialize door lock: %s", exc)
        raise


def initialize_button():
    """Initialize the button on GPIO17 with internal pull-up."""
    global button
    try:
        logger.info("Initializing button on GPIO17 (internal pull-up).")
        button = OutputDevice(BUTTON_PIN, pull_up=True, initial_value=False)
        logger.info("Button initialized on GPIO17.")
        return button
    except GPIOZeroError as exc:
        logger.error("Failed to initialize button: %s", exc)
        raise


def initialize_sound_mixer_and_lock():
    """Initialize the sound mixer and door lock."""
    sound_mixer = initialize_sound_mixer()
    door_lock = initialize_door_lock()
    return sound_mixer, door_lock


def recognize_face(face_recognizer, image):
    """Recognize a face in an image; return (confidence, label) or (None, None)."""
    try:
        label, confidence = face_recognizer.predict(image)
        if confidence < POSITIVE_THRESHOLD:
            logger.info("Recognized face with confidence %.2f (label: %s)", confidence, label)
            return label, confidence
        else:
            logger.info("No recognized face (confidence: %.2f).", confidence)
            return None, None
    except Exception as exc:
        logger.error("Face recognition failed: %s", exc)
        return None, None


def play_sound(sound_mixer, wave_path):
    """Play a sound wave file; return True on success, False on failure."""
    try:
        logger.info("Playing %s.", wave_path)
        sound_mixer.play(wave_path)
        return True
    except Exception as exc:
        logger.error("Failed to play %s: %s", wave_path, exc)
        return False


def play_welcome_sound():
    """Play the welcome sound."""
    if not play_sound(sound_mixer, SOUND_WAVES["welcome"]):
        logger.error("Failed to play welcome sound.")
        return False
    return True


def play_wait_sound():
    """Play the wait sound."""
    if not play_sound(sound_mixer, SOUND_WAVES["wait"]):
        logger.error("Failed to play wait sound.")
        return False
    return True


def play_later_sound():
    """Play the later sound."""
    if not play_sound(sound_mixer, SOUND_WAVES["later"]):
        logger.error("Failed to play later sound.")
        return False
    return True


def unlock_door():
    """Unlock the door if face is recognized."""
    if door is None:
        logger.error("Door lock not initialized.")
        return
    if not recognize_face(face_recognizer, door.lock_image()):
        logger.info("Door remains locked.")
        return
    logger.info("Door unlocked.")


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        face_recognizer = load_eigenfaces()
        sound_mixer, door_lock = initialize_sound_mixer_and_lock()
        door_lock = initialize_door_lock()
        button = initialize_button()
    except Exception as exc:
        logger.error("Initialization failed: %s", exc)
        sys.exit(1)

    logger.info("Starting main loop (0.1 s cadence). Press Ctrl+C to exit.")

    try:
        while _running:
            if button.is_active:
