import time
import signal
import sys
import board
import busio
import adafruit_pcf8574

# Proximity sensor pins (PCF8574 port pins)
SENSOR_PINS = [0, 1, 2, 3, 4, 5, 6, 7]
POLL_INTERVAL_S = 0.1
ERROR_DELAY_S = 1.0

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize I2C bus
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    # Initialize PCF8574 expander
    try:
        sensor_expander = adafruit_pcf8574.PCF8574(i2c)
    except Exception as e:
        print(f"Error initializing PCF8574 expander: {e}", file=sys.stderr)
        sys.exit(1)

    # Map sensor pins to PCF8574 port pins
    sensor_pins = [getattr(board, pin) for pin in SENSOR_PINS]
    try:
        sensor_expander.address = 0
    except Exception as e:
        print(f"Error setting PCF8574 address to 0: {e}", file=sys.stderr)
        sys.exit(1)

    # Initialize all sensors as outputs
    for i, pin in enumerate(sensor_pins):
        try:
            sensor_expander.output(pin, active_high=False, initial_value=False)
        except Exception as e:
            print(f"Error setting output pin {pin} on PCF8574: {e}", file=sys.stderr)
            sys.exit(1)

    print("Proximity sensor monitoring started. Press Ctrl+C to exit.")

    try:
        while _running:
            for i, pin in enumerate(sensor_pins):
                try:
                    if sensor_expander.input(pin):
                        print(f"Obstacle detected by sensor {i}")
                except Exception as e:
                    print(f"Error reading sensor {i}: {e}", file=sys.stderr)
                    time.sleep(ERROR_DELAY_S)

            time.sleep(POLL_INTERVAL_S)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        # Clean up resources
        try:
            for pin in sensor_pins:
                try:
                    sensor_expander.output(pin, active_high=False, initial_value=False)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            sensor_expander.deinit()
        except Exception:
            pass
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

