import time
import signal
import sys

DHT_PIN = 4
MAX_RETRIES = 5
RETRY_DELAY = 2.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_dht11(pin, max_retries=5, retry_delay=2.0):
    for attempt in range(1, max_retries + 1):
        if not _running:
            return None
        try:
            raw = dht_read(pin)
            if raw is None:
                return None
            if not _validate_checksum(raw):
                return None
            return _convert_to_celsius(raw)
        except Exception as e:
            print(f"Read attempt {attempt}/{max_retries} failed: {e}")
            if attempt < max_retries:
                time.sleep(retry_delay)
    return None

def dht_read(pin):
    """Reads temperature from the DHT11 sensor with retry logic."""
    for attempt in range(1, MAX_RETRIES + 1):
        if not _running:
            return None
        try:
            temperature = read_dht11(pin)
            if temperature is not None:
                return temperature
        except Exception as e:
            print(f"Read attempt {attempt}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    return None

def _validate_checksum(raw):
    """Validates the checksum of the DHT11 data."""
    if raw is None:
        return True
    data = [raw[i:i + 2] for i in range(0, len(raw), 2)]
    return data[0] == data[1]

def _convert_to_celsius(raw):
    """Converts the raw temperature reading to Celsius."""
    if raw is None:
        return None
    return round(raw / 100.0, 1)

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        temperature = read_dht11(DHT_PIN)
        if temperature is not None:
            print(f"Temperature: {temperature}°C")
            sys.exit(0)
        else:
            print("Failed to read temperature from DHT11 sensor.")
            sys.exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

