import signal
import sys
import time

import serial

PORT = "/dev/ttyUSB0"
BAUD_RATE = 115200
TIMEOUT = 1.0
READ_INTERVAL = 0.5

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def open_serial_port(port, baudrate, timeout):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {port}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error opening {port}: {exc}", file=sys.stderr)
        return None
    return ser


def read_temperature(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error reading from serial port: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error reading from serial port: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    try:
        line = raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        print(f"Error decoding ASCII data: {exc}", file=sys.stderr)
        return None

    if not line:
        return None

    try:
        return float(line)
    except ValueError:
        print(f"Error: malformed data received (not a number): {line!r}", file=sys.stderr)
        return None


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ser = open_serial_port(PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        sys.exit(1)

    try:
        while _running:
            temperature = read_temperature(ser)
            if temperature is not None:
                print(f"Temperature: {temperature:.1f} C")
            time.sleep(READ_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

