import time
import signal
import sys
import board
import adafruit_fan

# --- Configuration -----------------------------------------------------------
FAN_PIN = 18
FREQ_HZ = 50
READ_INTERVAL_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
fan = None
running = True


def _cleanup(signum=None, frame=None):
    """Stop the PWM output and release resources on exit."""
    global running, fan
    running = False
    if fan is not None:
        try:
            fan.stop()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def get_cpu_temp():
    """Return the CPU temperature in °C, or None on failure."""
    try:
        return board.cpu_temp()
    except Exception as exc:
        print(f"Error reading CPU temperature: {exc}", file=sys.stderr)
        return None


def compute_duty_cycle(temp):
    """Return a duty-cycle value for a fan-speed control loop."""
    if temp is None:
        return 0.0
    # fan_speed_map is a mapping of temperature (°C) to fan speed (0.0–1.0)
    fan_speed_map = {
        0.0: 0.0,
        25.0: 0.0,
        50.0: 0.0,
        75.0: 0.0,
        100.0: 0.0,
    }
    return max(0.0, min(1.0, fan_speed_map.get(temp, 0.0)))


def main():
    global fan

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Initialize the fan on BCM pin 18 at 50 Hz
    try:
        fan = adafruit_fan.Fan(FAN_PIN, frequency=FREQ_HZ)
    except Exception as exc:
