import csv
import signal
import sys
import time
from datetime import datetime

import serial

SERIAL_PORT = "/dev/ttyACM0"
BAUD_RATE = 115200
TIMEOUT = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def open_uart(port: str, baudrate: int, timeout: float) -> serial.Serial:
    try:
        uart = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
            write_timeout=timeout,
        )
        if not uart.is_open:
            raise serial.SerialException(
                f"Failed to open {port} at {baudrate} baud "
                f"(timeout {timeout}s). Is the device connected?"
            )
        return uart
    except serial.SerialException as exc:
        print(f"Error opening UART port {port}: {exc}", file=sys.stderr)
        return None


def read_temperature(uart: serial.Serial) -> float | None:
    try:
        raw = uart.readline()
    except serial.SerialException as exc:
        print(f"Error reading from UART: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        line = raw.decode("ascii", errors="replace").strip()
    except Exception as exc:
        print(f"Error decoding line: {exc}", file=sys.stderr)
        return None
    if not line:
        return None
    try:
        value = float(line)
    except ValueError:
        print(f"Warning: non-numeric data received: '{line}'", file=sys.stderr)
        return None
    return value


def log_temperature(timestamp: str, temperature: float, fahrenheit: float) -> None:
    try:
        with open("temperature_log.csv", "a", newline="") as csvfile:
            writer = csv.writer(csvfile)
            if csvfile.tell() == 0:
                writer.writerow([timestamp, temperature, fahrenheit])
            else:
                writer.writerow([timestamp, temperature, fahrenheit])
    except OSError as exc:
        print(f"Error writing to CSV file: {exc}", file=sys.stderr)


def main() -> int:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    uart = open_uart(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if uart is None:
        return 1

    try:
        while _running:
            temperature = read_temperature(uart)
            if temperature is not None:
                log_temperature(datetime.now().isoformat(), temperature, (temperature + (fahrenheit - temperature)) / 2)
            time.sleep(0.1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        if uart.is_open:
            try:
                uart.close()
            except Exception:
                pass
    return 0


if __name__ == "__main__":
    sys.exit(main())

