from http.client import HTTPConnection
from http.client import HTTPConnection

import requests

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

PIN = 4
BASE_URL = "http://localhost:5000/sensor"
USERNAME = "user"
PASSWORD = "pass"
REQUEST_TIMEOUT = 5
POLL_INTERVAL = 5

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


def _make_request(url, data, auth=None):
    conn = HTTPConnection(host="localhost", port=5000)
    try:
        conn.request("POST", url, json.dumps(data), auth=auth)
        response = conn.getresponse()
        if response.status != 200:
            logger.warning("API call returned %s", response.status)
            return None, response.status, response.read().decode("utf-8")
        return response, response.status, response.read().decode("utf-8")
    except (requests.exceptions.RequestException, OSError) as exc:
        logger.error("Network error: %s", exc)
        return None, None, str(exc)
    finally:
        conn.close()


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with open("config.json", "r") as f:
            config = json.load(f)
        pin = config.get("pin", PIN)
        base_url = config.get("base_url", BASE_URL)
        username = config.get("username", USERNAME)
        password = config.get("password", PASSWORD)
        request_timeout = config.get("request_timeout", REQUEST_TIMEOUT)
        poll_interval = config.get("poll_interval", POLL_INTERVAL)
    except (FileNotFoundError, json.JSONDecodeError) as exc:
        logger.error("Configuration error: %s", exc)
        sys.exit(1)

    try:
        with open("config.json", "w") as f:
            json.dump(config, f, indent=2)
    except OSError as exc:
        logger.error("Cannot write config: %s", exc)
        sys.exit(1)

    logger.info("Starting temperature sensor monitor (pin=%d, base_url=%s, username=%s, password=%s, request_timeout=%s)",
                pin, base_url, username, password, request_timeout)

    try:
        while _running:
            try:
                state = config.get("sensor", "Temperature").lower()
                if state not in ("0", "1"):
                    raise ValueError(f"Invalid sensor value: {state}")
                value = int(state)

                payload = {"sensor": "Temperature", "value": value}
                response, status, response_text = _make_request(
                    base_url, payload, auth=(username, password)
                )

                if response is None:
                    logger.warning("API call failed, status=%s, text=%s", status, response_text)
                else:
                    logger.info("API call succeeded, status=%s, text=%s", status, response_text)

                if response_text:
                    logger.info("Response: %s", response_text)

            except (ValueError, KeyError) as exc:
                logger.warning("Invalid sensor value: %s", exc)
            except Exception as exc:
                logger.error("Unexpected error: %s", exc)

            if _running:
                time.sleep(poll_interval)

    except Exception as exc:
        logger.error("Fatal error: %s", exc)
    finally:
        logger.info("Shutting down...")


if __name__ == "__main__":
    main()

