import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle for cleanup
sensor = None

def cleanup(signum=None, frame=None):
    """Release the DHT11 sensor on exit or signal."""
    global sensor
    if sensor is not None:
        try:
            sensor.exit()
        except Exception:
            pass
        sensor = None
    if signum is not None:
        sys.exit(0)

def main():
    global sensor

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize the DHT11 sensor on board.D4 (BCM pin 7)
    try:
        sensor = adafruit_dht.DHT11(board.D4)
    except Exception as e:
        print(f"Error initializing DHT11 sensor: {e}")
        sys.exit(1)

    try:
        while True:
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity

                if temperature is None or humidity is None:
                    print("Sensor returned None values.")
                    continue

                print(f"Temperature: {temperature:.1f} C")
                print(f"Humidity: {humidity:.1f} %")

            except RuntimeError as e:
                # DHT11 can throw RuntimeError on checksum or timing issues
                print(f"Sensor read error: {e}")
            except Exception as e:
                # Catch any other unexpected errors
                print(f"Unexpected error: {e}")

            # Wait 5 seconds before the next reading
            time.sleep(5)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        cleanup()

if __name__ == '__main__':
    main()

