import time
import signal
import sys
import board
import busio
import adafruit_bmp280

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize I2C bus 1
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        sys.exit(1)

    # Initialize BMP280 altitude monitor
    try:
        bmp = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=0x77)
    except Exception as e:
        print(f"Error initializing BMP280 at address 0x77: {e}")
        sys.exit(1)

    # Baseline pressure reading
    baseline_pressure = None
    try:
        baseline_pressure = bmp.sea_level_pressure
        print(f"Baseline pressure: {baseline_pressure:.2f} hPa")
    except ValueError as e:
        print(f"Error reading baseline pressure: {e}")
        sys.exit(1)
    except OSError as e:
        print(f"Error reading baseline pressure: {e}")
        sys.exit(1)

    # Exclude first two readings for stability
    if baseline_pressure is not None:
        baseline_pressure = baseline_pressure[2:]
    else:
        print("Error: Baseline pressure not available.")
        sys.exit(1)

    # Main loop
    try:
        while running:
            try:
                # Read altitude at 1-second interval
                altitude = bmp.altitude
                if altitude is not None:
                    print(f"Relative altitude: {altitude:.2f} meters")
                else:
                    print("Error: Failed to read altitude.")
            except OSError as e:
                print(f"Error reading altitude: {e}")
            except ValueError as e:
                print(f"Error calculating altitude: {e}")
            except Exception as e:
                print(f"Unexpected error reading altitude: {e}")

            # Wait for 1 second
            time.sleep(1)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean up resources
        try:
            bmp.deinit()
        except Exception:
            pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

