#!/usr/bin/env python3
"""
Sunrise/sunset LED lighting controller for Raspberry Pi.

Hardware:
  - LED on BCM pin 17 (hardware PWM at 100 Hz).
  - DHT22 on BCM pin 4 (optional).

Wiring:
  - LED anode to BCM pin 17 (via 220 Ω resistor).
  - LED cathode to GND.
  - DHT22 data pin to BCM pin 4 (via 220 Ω resistor).
  - DHT22 VCC to 3.3 V, DHT22 GND to GND.

Dependencies:
  - gpiozero (for hardware PWM)
  - adafruit-circuitpython-dht (for DHT22)
  - RPi.GPIO (for GPIO access)
"""

import json
import signal
import sys
import time
from datetime import datetime

import board
import adafruit_dht
import RPi.GPIO as GPIO
from gpiozero import PWMOutputDevice

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LED_PIN = 17
DHT_PIN = 4
PWM_FREQUENCY = 100          # Hz
DUTY_CYCLE_MAX = 90          # %
DUTY_CYCLE_MIN = 0           # %
DUTY_CYCLE_STEP = 1          # %
SLEEP_TIME = 10              # seconds between ramp-down/up cycles
SLEEP_DURATION = 600         # seconds between sunrise/sunset cycles
DHT_READ_INTERVAL = 5         # seconds between DHT22 reads

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_led = None
_dht = None
_running = True


def _cleanup() -> None:
    """Release all hardware resources safely."""
    global _led, _dht
    if _led is not None:
        try:
            _led.value = 0.0
            _led.close()
        except Exception:
            pass
        _led = None
    if _dht is not None:
        try:
            _dht.exit()
        except Exception:
            pass
        _dht = None


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


