import urllib.request

import board
import adafruit_dht

API_ENDPOINT = "http://127.0.0.1:5000/data"
READ_INTERVAL_S = 5
SENSOR_PIN = board.D4  # GPIO4 (physical pin 7)

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_sensor(sensor):
    """Read temperature and humidity from the DHT11; return (temp, hum) or (None, None) on failure."""
    try:
        temp = sensor.temperature
        hum = sensor.humidity
        if temp is None or hum is None:
            return None, None
        return temp, hum
    except RuntimeError as exc:
        # DHT11 often throws transient read errors; retry on the next cycle.
        return None, None
    except Exception as exc:
        print(f"Sensor read error: {exc}", file=sys.stderr)
        return None, None


def post_data(payload):
    """POST the JSON payload to the API endpoint; return HTTP status code on success."""
    try:
        req = urllib.request.Request(API_ENDPOINT, data=payload.encode("utf-8"), method="POST")
        req.add_header("Content-Type", "application/json")
        with urllib.request.urlopen(req, timeout=10) as resp:
            if 200 <= resp.status < 300:
                print(f"HTTP {resp.status} - {resp.reason}")
            else:
                print(f"HTTP {resp.status} - unexpected response")
    except urllib.error.URLError as exc:
        print(f"Network error: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error posting data: {exc}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        sensor = adafruit_dht.DHT11(SENSOR_PIN, use_pulseio=False)
        print("DHT11 sensor initialized on GPIO4 (BCM).")

        while _running:
            temp, hum = read_sensor(sensor)
            if temp is not None and hum is not None:
                payload = {"temperature": temp, "humidity": hum}
                post_data(payload)
            else:
                print("Skipping this cycle due to sensor read failure.")

            # Sleep in small increments so signals are caught promptly.
            slept = 0.0
            while _running and slept < READ_INTERVAL_S:
                time.sleep(0.1)
                slept += 0.1

    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
    finally:
        if sensor is not None:
            try:
                sensor.exit()
            except Exception:
                pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

