last_duty_cycle = 100
running = True

def get_cpu_temp():
    """Read CPU temperature via vcgencmd and return Celsius or None on failure."""
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True, text=True, timeout=5,
        )
        if result.returncode != 0:
            print(f"vcgencmd failed (exit {result.returncode}): {result.stderr.strip()}", file=sys.stderr)
            return None
        return float(result.stdout.strip())
    except subprocess.TimeoutExpired:
        print("vcgencmd timed out", file=sys.stderr)
        return None
    except subprocess.CalledProcessError as e:
        print(f"vcgencmd failed: {e.stderr.strip()}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading CPU temp: {e}", file=sys.stderr)
        return None

def get_fan_duty_cycle(cpu_temp):
    """Return the duty cycle for the fan given the CPU temperature."""
    if cpu_temp is None:
        return last_duty_cycle
    return int(round(cpu_temp / 10.0))

