import RPi.GPIO as GPIO
import time
import sys

# GPIO pin for the LED (BCM numbering)
LED_PIN = 17

# Initialize GPIO with error handling
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
except Exception as e:
    print(f"GPIO setup failed: {e}")
    sys.exit(1)

led_state = False

def cleanup():
    """Safely clean up GPIO resources."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup error: {e}")

def main():
    global led_state
    try:
        while True:
            user_input = input("Enter 'on' or 'off' (or 'exit'): ").strip().lower()
            if user_input == "exit":
                print("Exiting program.")
                break
            if user_input == "on":
                led_state = True
                print(f"LED is ON")
            elif user_input == "off":
                led_state = False
                print(f"LED is OFF")
            else:
                print("Invalid input")
    except EOFError:
        print("\nEOF received, exiting.")
    except KeyboardInterrupt:
        print("\nKeyboard interrupt received, exiting.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

