import time
import signal
import sys
import board
import busio
import adafruit_seesaw.seesaw_i2c
import adafruit_seesaw.seesaw_i2c_pin

# --- Configuration -----------------------------------------------------------
I2C_BUS_NUMBER = 1
I2C_SCL_PIN = board.SCL
I2C_SDA_PIN = board.SDA
PUMP_PIN = 17
MOISTURE_THRESHOLD = 300
READ_INTERVAL_SECONDS = 10

# --- Globals for cleanup ------------------------------------------------------
_running = True
_i2c = None
_pump = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _i2c, _pump
    if _pump is not None:
        try:
            _pump.off()
        except Exception:
            pass
        _pump = None
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None


def _read_soil_moisture():
    """Read the soil moisture sensor and return the raw value (0-1023)."""
    try:
        i2c = busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        return None

    try:
        moisture = i2c.read_byte(adafruit_seesaw.seesaw_i2c.SENSOR_ADDRESS)
    except Exception as exc:
        print(f"Error reading soil moisture: {exc}", file=sys.stderr)
        return None

    if moisture is None:
        print("Error: Sensor absent or read failed.", file=sys.stderr)
        return None

    return moisture


def _drive_pump(moisture):
    """Drive the water pump based on the moisture reading."""
    if moisture is None:
        return
    if moisture < MOISTURE_THRESHOLD:
        print("Water pump ON: Soil moisture low")
        try:
            _pump.on()
        except Exception as exc:
            print(f"Error turning pump ON: {exc}", file=sys.stderr)
    else:
        print("Water pump OFF: Soil moisture normal")
        try:
            _pump.off()
        except Exception as exc:
            print(f"Error turning pump OFF: {exc}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _i2c = busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _pump = _i2c.get_device(adafruit_seesaw.seesaw_i2c.SENSOR_ADDRESS)
    except Exception as exc:
        print(f"Error initializing water pump: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            moisture = _read_soil_moisture()
            if moisture is not None:
                _drive_pump(moisture)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

