REG_GPIOB = 0x09
REG_GPIO_INP = 0x0C
REG_GPIO_OUT = 0x0D
REG_GPIO_INT = 0x0E
REG_GPIO_INT_CLR = 0x0F
REG_GPIO_INT_SET = 0x10
REG_GPIO_INT_MUX = 0x11
REG_GPIO_INT_MUX_SWITCH_PULL_UP = 0x11
REG_GPIO_INT_MUX_SWITCH_PULL_DOWN = 0x12
REG_GPIO_INT_MUX_SWITCH_PULL_UP_AND_PULL_DOWN = 0x13
REG_GPIO_INT_MUX_SWITCH_PULL_UP_AND_PULL_DOWN_AND_PULL_UP = 0x14
REG_GPIO_INT_MUX_SWITCH_PULL_UP_AND_PULL_DOWN_AND_PULL_UP_AND_PULL_DOWN = 0x15
REG_GPIO_INT_MUX_SWITCH_PULL_UP_AND_PULL_DOWN_AND_PULL_UP_AND_PULL_DOWN_AND_PULL_UP = 0x16
REG_GPIO_INT_MUX_SWITCH_PULL_UP_AND_PULL_DOWN_AND_PULL_UP_AND_PULL_DOWN_AND_PULL_UP_AND_PULL_DOWN_AND_PULL_UP = 0x17
REG_GPIO_INT_MUX_SWITCH_PULL_UP_AND_PULL_DOWN_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP = 0x18
REG_GPIO_INT_MUX_SWITCH_PULL_UP_AND_PULL_DOWN_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP = 0x19
REG_GPIO_INT_MUX_SWITCH_PULL_UP_AND_PULL_DOWN_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP_AND_PULL_UP = 0x1A
