import signal
import sys
import time

import RPi.GPIO as GPIO

SENSOR_PINS = {
    1: 17,
    2: 27,
    3: 22,
}
POLL_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _init_gpio(sensor_pins):
    try:
        GPIO.setmode(GPIO.BCM)
        for pin, bcm_pin in sensor_pins.items():
            GPIO.setup(bcm_pin, GPIO.IN, pull_up=True)
    except Exception as exc:
        print(f"GPIO initialization failed: {exc}", file=sys.stderr)
        raise


def _read_sensor(sensor_pin):
    try:
        return GPIO.input(sensor_pin)
    except Exception as exc:
        print(f"Error reading sensor {sensor_pin}: {exc}", file=sys.stderr)
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        _init_gpio(SENSOR_PINS)
    except Exception as exc:
        print(f"Fatal: GPIO initialization failed: {exc}", file=sys.stderr)
        sys.exit(1)

    print("Monitoring sensors on GPIO 17, GPIO 27, GPIO 22 (active-high, pull_up=True)")
    print(f"Poll interval: {POLL_INTERVAL_S}s")

    try:
        while _running:
            sensor_values = {
                1: _read_sensor(SENSOR_PINS[1]),
                2: _read_sensor(SENSOR_PINS[2]),
                3: _read_sensor(SENSOR_PINS[3]),
            }

            for sensor_id, value in sensor_values.items():
                if value is None:
                    print(f"Warning: sensor {sensor_id} returned None")
                else:
                    print(f"Response for sensor {sensor_id}")

            time.sleep(POLL_INTERVAL_S)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

