import json
import signal
import sys
import time
from typing import Optional

import requests
from gpiozero import DigitalInputDevice

USER = "user"
PASSWORD = "password"
ENDPOINT = "http://localhost:5000/sensor"
POLL_INTERVAL = 5  # seconds

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup() -> None:
    """Release GPIO resources and exit cleanly."""
    try:
        if 'sensor' in dir(DigitalInputDevice) and hasattr(
            DigitalInputDevice, 'close'
        ):
            DigitalInputDevice.close()
    except Exception:
        pass
    try:
        requests.delete(ENDPOINT, auth=requests.auth.HTTPBasicAuth(USER, PASSWORD))
    except Exception:
        pass


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensor = None
    try:
        sensor = DigitalInputDevice(
            pin=4,
            pull_up=False,
            bounce_time=None,
        )
    except Exception as exc:
        print(f"Failed to initialize GPIO pin 4: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                value = sensor.value
            except Exception as exc:
                print(f"Sensor read error: {exc}", file=sys.stderr)
                time.sleep(POLL_INTERVAL)
                continue

            payload = {
                "sensor": "digital_input",
                "value": value,
            }
            try:
                response = requests.post(
                    ENDPOINT,
                    json=payload,
                    auth=requests.auth.HTTPBasicAuth(USER, PASSWORD),
                    timeout=10,
                )
            except requests.exceptions.RequestException as exc:
                print(f"Request error: {exc}", file=sys.stderr)
                time.sleep(POLL_INTERVAL)
                continue

            if response.status_code == 200:
                print(f"Sensor value: {value}")
            else:
                print(f"Unexpected HTTP status {response.status_code} for sensor read", file=sys.stderr)

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()
    return 0


if __name__ == "__main__":
    sys.exit(main())

