import argparse
import signal
import sys
import time
import threading
import logging
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Global flag for graceful shutdown
_shutdown_requested = threading.Event()


def signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    logger.info(f"Received signal {signum}, initiating graceful shutdown...")
    _shutdown_requested.set()


def _log_data(data_string):
    """Logs data to the file and sends it via DOG.send()."""
    try:
        with open('dogs.log', 'a') as log_file:
            log_file.write(data_string + '\n')
            log_file.flush()
            logger.info(f"Data logged: {data_string}")
            dogs.send(data_string)
    except IOError as e:
        logger.error(f"Error writing to log file: {e}")
    except Exception as e:
        logger.error(f"Unexpected error writing to log file: {e}")


def _send_data(data_string):
    """Sends data via DOG.send()."""
    try:
        dogs.send(data_string)
        logger.info(f"Data sent via DOG: {data_string}")
    except Exception as e:
        logger.error(f"Error sending data: {e}")


def _read_data():
    """Reads data from the file and sends it via DOG.send()."""
    try:
        with open('dogs.log', 'r') as log_file:
            data = log_file.read()
            if data:
                logger.info(f"Data received from file: {data}")
                dogs.send(data)
    except IOError as e:
        logger.error(f"Error reading from log file: {e}")
    except Exception as e:
        logger.error(f"Unexpected error reading from log file: {e}")


def _stop_api_call():
    """Stops the DOG API call and releases GPIO resources."""
    try:
        if dogs.api_call_started:
            dogs.api_call_stopped()
            logger.info("DOG API call stopped.")
    except Exception as e:
        logger.error(f"Error stopping API call: {e}")
    finally:
        try:
            dogs.api_call_stopped()
            logger.info("DOG API call stopped.")
        except Exception as e:
            logger.error(f"Error stopping API call: {e}")


def _cleanup_gpio():
    """Clean up GPIO resources."""
    try:
        for dev in dogs.gpio_devices.values():
            dev.close()
        logger.info("GPIO cleanup complete.")
    except Exception as e:
        logger.error(f"Error during GPIO cleanup: {e}")


def _cleanup_and_exit():
    """Clean up GPIO and exit."""
    _shutdown_requested.set()
