    global _led
    try:
        _led = LED(LED_PIN)
        logger.info('LED initialized on GPIO %d', LED_PIN)
    except Exception as exc:
        logger.error('Failed to initialize LED on GPIO %d: %s', LED_PIN, exc)
        _led = None


def _init_server():
