    try:
        _led.off()
        return _html_template(
            '<html><head><title>LED Control</title></head><body><h1>LED Control</h1><ul><li><a href="/light_on">Turn LED on</a></li><li><a href="/light_off">Turn LED off</a></li></ul><p><a href="/">Back to index</a></p></body></html>'
        )
    except Exception as exc:
        logger.error('Error turning LED off: %s', exc)
        return _internal_server_error(request)


def _not_found(request):
    return _html_template(
        '<html><head><title>LED Control</title></head><body><h1>Page not found</h1><p>Try <a href="/">home</a>.</p></body></html>'
    )


def _html_template(body):
    return f'<html><head><title>LED Control</title></head><body>{body}</body></html>'


def _internal_server_error(request):
    return _html_template(
        '<html><head><title>Internal Server Error</title></head><body><h1>Internal Server Error</h1><p>Something went wrong. Please try again.</p></body></html>'
    )


