import signal
import sys
import time

from gpiozero import Button, LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

BUTTON_PIN = 4
LED_PIN = 17
POLL_INTERVAL = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        button = Button(BUTTON_PIN, pull_up=False, bounce_time=0.05)
        led = LED(LED_PIN)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize GPIO devices: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            if not _running:
                break

            try:
                if button.is_pressed:
                    led.on()
                else:
                    led.off()
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Warning: GPIO error during polling: {exc}", file=sys.stderr)
                time.sleep(POLL_INTERVAL)
                continue

            time.sleep(POLL_INTERVAL)
    finally:
        try:
            led.close()
        except Exception:
            pass
        try:
            button.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

