        print(f"Error initializing fingerprint sensor: {e}")
        raise


def initialize_image_capture():
    """Initializes the image capture module."""
    global image_capture
    try:
        image_capture = adafruit_image_capture.ImageCapture(
            i2c_bus, address=FINGERPRINT_I2C_ADDRESS
        )
        print("Image capture initialized successfully.")
    except Exception as e:
        print(f"Error initializing image capture: {e}")
        raise


def get_image():
    """Captures an image from the fingerprint sensor."""
    global image_capture
    try:
        return image_capture.capture_image()
    except Exception as e:
        print(f"Error capturing image: {e}")
        raise


def get_fingerprint_image(image_data):
    """Converts the image data to a fingerprint template."""
    global fingerprint_sensor
    try:
        fingerprint_data = fingerprint_sensor.get_fingerprint(image_data)
        return fingerprint_data
    except Exception as e:
        print(f"Error getting fingerprint data: {e}")
        raise


def search_database(fingerprint_data):
    """Searches the fingerprint database for a match."""
    global fingerprint_sensor
    try:
        return fingerprint_sensor.fingerprint_search(fingerprint_data)
    except Exception as e:
        print(f"Error searching database: {e}")
        return None


def authenticate_user(fingerprint_data, confidence_score):
    """Authenticates a user against the fingerprint database."""
    global fingerprint_sensor
    try:
        if fingerprint_data is None:
            print("No fingerprint data to authenticate.")
            return False

        if confidence_score is None:
            print("No confidence score to authenticate.")
            return False

        if fingerprint_data.get('id') != FINGERPRINT_IMAGE_2_ID:
            print("Incorrect fingerprint ID.")
            return False

        return True
    except Exception as e:
        print(f"Error authenticating user: {e}")
        return False


def print_access_granted(matched_id, confidence_score):
    """Prints the access granted message."""
    print(f"Access Granted! Matched ID: {matched_id}, Confidence Score: {confidence_score}")


def print_access_denied():
    """Prints the access denied message."""
    print("Access Denied")


def cleanup():
    """Cleans up resources."""
    global i2c_bus, fingerprint_sensor, image_capture
    print("Cleaning up resources...")
    if i2c_bus:
        try:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        except Exception as e:
            print(f"Error deinitializing I2C bus: {e}")
    if fingerprint_sensor:
        try:
            fingerprint_sensor.close()
            print("Fingerprint sensor closed.")
        except Exception as e:
            print(f"Error closing fingerprint sensor: {e}")
    if image_capture:
        try:
            image_capture.close()
            print("Image capture closed.")
        except Exception as e:
            print(f"Error closing image capture: {e}")
    print("Cleanup complete.")


def main():
    """Main function to run the fingerprint authentication."""
    global running
    try:
        initialize_i2c()
        initialize_fingerprint_sensor()
        initialize_image_capture()

        print("Fingerprint Authentication System Started. Press Ctrl+C to exit.")

        while running:
            try:
                image_data = get_image()
                fingerprint_data = get_fingerprint_image(image_data)
                matched_id = search_database(fingerprint_data)

                if matched_id:
                    print_access_granted(matched_id, fingerprint_data['confidence_score'])
                else:
                    print_access_denied()

                time.sleep(FINGERPRINT_IMAGE_2_RETRY_DELAY)

            except ValueError:
                print("Error: Could not read image data from sensor.")
                time.sleep(FINGERPRINT_IMAGE_2_RETRY_DELAY)
                continue

            except Exception as e:
                print(f"An unexpected error occurred: {e}")
                time.sleep(FINGERPRINT_IMAGE_2_RETRY_DELAY)
                continue

    except KeyboardInterrupt:
        print("\nExiting program...")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

