import socket
import logging
import signal
import sys

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)

BACKLIGHT_GPIO_PIN = 24
LISTENER_PORT = 9100
ACCEPT_TIMEOUT = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    logging.info("Signal %s received, shutting down...", signum)
    _running = False

def _send_reply(conn, reply):
    try:
        conn.sendall(reply.encode("utf-8"))
    except Exception as exc:
        logging.error("Error sending reply: %s", exc)

def _handle_command(conn, command):
    if command == "on":
        try:
            GPIO.output(BACKLIGHT_GPIO_PIN, GPIO.HIGH)
            logging.info("Backlight turned ON")
        except Exception as exc:
            logging.error("Failed to turn backlight ON: %s", exc)
    elif command == "off":
        try:
            GPIO.output(BACKLIGHT_GPIO_PIN, GPIO.LOW)
            logging.info("Backlight turned OFF")
        except Exception as exc:
            logging.error("Failed to turn backlight OFF: %s", exc)
    else:
        logging.info("Unknown command: %s", command)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        listener.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        listener.bind(("0.0.0.0", LISTENER_PORT))
        listener.listen(1)
        logging.info("Listening on port %d...", LISTENER_PORT)
    except socket.error as exc:
        logging.error("Failed to bind socket: %s", exc)
        return

    try:
        while _running:
            try:
                conn, addr = listener.accept()
            except socket.error as exc:
                logging.error("Accept failed: %s", exc)
                break

            try:
                command = conn.recv(64).decode("utf-8", errors="replace")
            except socket.error as exc:
                logging.error("Receive failed: %s", exc)
                break

            if not _running:
                break

            _handle_command(conn, command)
            _send_reply(conn, "backlight on")
            _send_reply(conn, "backlight off")
            _send_reply(conn, "unknown command")
    finally:
        try:
            listener.close()
        except Exception:
            pass
        logging.info("Socket closed and GPIO cleaned up.")

if __name__ == "__main__":
    main()

