import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: sudo apt install python3-rpi.gpio")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQUENCY = 25000

running = True

def signal_handler(signum, frame):
    global running
    running = False

def get_fan_speed():
    while True:
        try:
            user_input = input("Enter fan speed (0-100): ").strip()
            if user_input.isdigit() and 0 <= int(user_input) <= 100:
                return int(user_input)
            print("Invalid input. Please enter a number between 0 and 100.")
        except EOFError:
            print("\nEOF received. Exiting.")
            return None
        except ValueError:
            print("Invalid input. Please enter a number.")

def set_fan_speed(fan_speed):
    try:
        GPIO.output(FAN_PIN, GPIO.HIGH if fan_speed > 0 else GPIO.LOW)
        GPIO.wait_for_edge(FAN_PIN, GPIO.FALLING)
        fan_duty = fan_speed / 100.0
        GPIO.output(FAN_PIN, GPIO.HIGH if fan_duty > 0 else GPIO.LOW)
        print(f"Fan speed set to {fan_duty:.1f}%")
    except Exception as e:
        print(f"Error setting fan speed: {e}")

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

    try:
        while running:
            fan_speed = get_fan_speed()
            if fan_speed is not None:
                set_fan_speed(fan_speed)
            time.sleep(0.1)
    finally:
        GPIO.output(FAN_PIN, GPIO.LOW)
        GPIO.cleanup()
        print("Fan stopped and GPIO cleaned up.")

if __name__ == "__main__":
    main()

