import time
import signal
import sys

LED_PIN = 17
ON_DURATION = 0.5
OFF_DURATION = 0.5

running = True

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    led = None
    try:
        led = GPIO.output(LED_PIN, GPIO.HIGH)
        print(f"LED initialized on GPIO{LED_PIN} (BCM). Starting at OFF state.")

        while running:
            time.sleep(0.1)
            if not running:
                break

            led_state = GPIO.input(LED_PIN)
            if led_state == GPIO.HIGH:
                print("LED is ON")
            else:
                print("LED is OFF")

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if led is not None:
            try:
                GPIO.output(LED_PIN, GPIO.LOW)
                print("LED turned off and resources released.")
            except Exception:
                pass
        print("Program finished.")

if __name__ == "__main__":
    main()

