import time
import signal
import sys
from gpiozero import LED

LED_PIN = 17
ON_DURATION = 1.0
OFF_DURATION = 1.0

led = None

def cleanup(signum=None, frame=None):
    """Release the GPIO pin on exit."""
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        sys.exit(0)

def main():
    global led
    try:
        led = LED(LED_PIN)
    except (gpiozero.PinNoPins, BadPinFactory) as exc:
        print(f"Error: GPIO pin {LED_PIN} is not available or invalid: {exc}")
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error initializing GPIO: {exc}")
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        while True:
            led.on()
            time.sleep(ON_DURATION)
            led.off()
            time.sleep(OFF_DURATION)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()

if __name__ == "__main__":
    main()

