import time
import signal
import sys

LED_PIN = 17

led_on = False
led_off = False

def cleanup(signum=None, frame=None):
    """Turn the LED off and release the pin on exit."""
    global led_on, led_off
    led_on = False
    led_off = False
    try:
        if led_on:
            led_on = False
            print("LED off – Program stopped")
    except Exception:
        pass
    try:
        if led_off:
            led_off = False
            print("LED off – Program stopped")
    except Exception:
        pass
    try:
        if signum is not None:
            sys.exit(0)
    except SystemExit:
        pass
    finally:
        try:
            import RPi.GPIO as GPIO
            GPIO.cleanup()
        except Exception:
            pass

def main():
    global led_on, led_off
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        while True:
            if led_on:
                GPIO.output(LED_PIN, GPIO.HIGH)
                print("LED on")
            else:
                GPIO.output(LED_PIN, GPIO.LOW)
                print("LED off")
            time.sleep(0.5)
    except KeyboardInterrupt:
        cleanup()
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

