import random
import time
import signal
import sys

LED_PIN = 17
NUM_CYCLES = 5
DELAY_SECONDS = 2

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def simulate_light_level():
    """Return a random integer light level between 0 and 100 percent."""
    return random.randint(0, 100)


def control_led(level, is_on):
    """Set the LED state and print the light level."""
    if is_on:
        print(f"LED is ON: {level}%")
    else:
        print(f"LED is OFF: {level}%")


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        for cycle in range(1, NUM_CYCLES + 1):
            if not _running:
                break
            light_level = simulate_light_level()
            control_led(light_level, False)
            time.sleep(DELAY_SECONDS)
        print("Simulation complete.")
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
