import time
import signal
import sys
import board
import busio
import adafruit_seesaw.seesaw

# Configuration
DRY_SOIL_THRESHOLD = 500
PUMP_PIN = 17
POLL_INTERVAL = 10  # seconds

# Global state for signal handling
_running = True
_pump_state = "OFF"


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT or SIGTERM."""
    global _running
    _running = False


def read_soil_moisture():
    """Read the soil moisture sensor and return the value (0-1023)."""
    try:
        # Adafruit Seesaw uses a capacitive sensor; the raw value is the
        # raw ADC reading (0-1023).
        return adafruit_seesaw.seesaw.raw_value
    except Exception as exc:
        print(f"Error reading soil moisture: {exc}", file=sys.stderr)
        return None


def control_pump(moisture_level):
    """Drive the water pump based on the moisture level."""
    global _pump_state

    if moisture_level is None:
        _pump_state = "UNKNOWN"
    elif moisture_level < DRY_SOIL_THRESHOLD:
        _pump_state = "ON"
    else:
        _pump_state = "OFF"

    print(f"Moisture: {moisture_level}, Pump: {'ON' if _pump_state == "ON" else 'OFF'}")


def main():
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize I2C bus
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    # Initialize Seesaw soil moisture sensor
    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c)
    except Exception as exc:
        print(f"Error initializing Seesaw sensor: {exc}", file=sys.stderr)
        i2c.deinit()
        sys.exit(1)

    # Ensure pump is off at startup
    try:
        sensor.value = 0
    except Exception as exc:
        print(f"Warning: could not initialize sensor: {exc}", file=sys.stderr)

    print("Soil moisture monitor started. Press Ctrl+C to stop.")

    try:
        while _running:
            moisture = read_soil_moisture()

            if moisture is not None:
                control_pump(moisture)
            else:
                print("Sensor read failed; pump remains off.", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < POLL_INTERVAL:
                time.sleep(0.1)
                slept += 0.1

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        # Ensure pump is off and resources are released
        try:
            sensor.value = 0
        except Exception:
            pass
        try:
            sensor.close()
        except Exception:
            pass
        try:
            i2c.deinit()
        except Exception:
            pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

