import paho.mqtt.client as mqtt
import logging
import time
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class UrbanClassifier:
    def __init__(self, broker_address, broker_port, report_topic, classification_topic):
        self.broker_address = broker_address
        self.broker_port = broker_port
        self.report_topic = report_topic
        self.classification_topic = classification_topic
        self.client = None
        self.running = False

    def connect(self):
        try:
            self.client = mqtt.Client(
                mqtt.CallbackAPIVersion.VERSION2,
                client_id="urban_classifier"
            )
            self.client.on_connect = self._on_connect
            self.client.on_disconnect = self._on_disconnect
            self.client.on_message = self._on_message
            self.client.connect(self.broker_address, self.broker_port, keepalive=60)
            self.client.loop_start()
            logging.info("Connected to MQTT broker at %s:%s", self.broker_address, self.broker_port)
            return True
        except Exception as e:
            logging.error("Failed to connect to MQTT broker: %s", e)
            self.client = None
            return False

    def _on_connect(self, client, userdata, flags, reason_code, properties):
        if reason_code == 0:
            logging.info("Connected to MQTT broker")
        else:
            logging.error("MQTT connection failed with reason code: %s", reason_code)

    def _on_disconnect(self, client, userdata, flags, reason_code, properties):
        logging.info("Disconnected from MQTT broker (reason code: %s)", reason_code)

    def _on_message(self, client, userdata, message):
        try:
            payload = message.payload.decode('utf-8')
            logging.info("Received message: %s", payload)
            report_text = payload.strip()
            classification = self.classify_report(report_text)
            self.publish_classification(classification)
        except Exception as e:
            logging.error("Error processing MQTT message: %s", e)

    def classify_report(self, report_text):
        if not report_text:
            return "noise"
        if "traffic" in report_text:
            return "traffic"
        if "other" in report_text:
            return "other"
        return "noise"

    def publish_classification(self, classification):
        try:
            self.client.publish(self.classification_topic, classification)
            logging.info("Published classification: %s", classification)
        except Exception as e:
            logging.error("Failed to publish classification: %s", e)

    def shutdown(self):
        if self.client:
            try:
                self.client.loop_stop()
                self.client.disconnect()
                logging.info("Disconnected from MQTT broker")
            except Exception as e:
                logging.error("Error during MQTT shutdown: %s", e)
        logging.info("Classifier shutdown complete")

    def run(self):
        if not self.connect():
            self.shutdown()
            return
        try:
            while self.running:
                time.sleep(0.1)
        except KeyboardInterrupt:
            self.shutdown()
        finally:
            self.shutdown()

def main():
    classifier = UrbanClassifier("localhost", 1883, "city/reports", "city/classification")
    signal.signal(signal.SIGINT, lambda s, f: sys.exit(0))
    signal.signal(signal.SIGTERM, lambda s, f: sys.exit(0))
    try:
        classifier.run()
    except Exception as e:
        logging.error("Unexpected error: %s", e)
        sys.exit(1)

if __name__ == "__main__":
    main()

