import sys

try:
    import smbus2 as smbus
except ImportError:
    import smbus

I2C_BUS_NUMBER = 1
I2C_ADDRESS = 0x10

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _safe_write(bus, register, value):
    try:
        bus.write_byte_data(I2C_ADDRESS, register, value)
    except OSError as exc:
        raise RuntimeError(f"I2C write failed at 0x{register:02X}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected write error at 0x{register:02X}: {exc}") from exc


def _safe_read(bus, register):
    try:
        return bus.read_byte_data(I2C_ADDRESS, register)
    except OSError as exc:
        raise RuntimeError(f"I2C read failed at 0x{register:02X}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected read error at 0x{register:02X}: {exc}") from exc


def _probe_device(bus, address):
    try:
        bus.read_byte_data(address, 0)
    except OSError as exc:
        raise RuntimeError(f"Device not found at 0x{address:02X}: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected device probe error at 0x{address:02X}: {exc}") from exc


def _close_bus(bus):
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass


def _register_device(bus, address, register, value):
    _safe_write(bus, register, value)
    _safe_read(bus, register)


def _register_device_with_context(bus, address, register, value):
    with _safe_write(bus, register, value):
        with _safe_read(bus, register):
            return value


def register_device(bus, address, register, value):
    _register_device(bus, address, register, value)


def close_bus(bus):
    _close_bus(bus)


class I2C_Device:
    def __init__(self, address, bus_number=I2C_BUS_NUMBER):
        self.address = address
        self.bus_number = bus_number
        self.bus = None
        self._running = True

    def __enter__(self):
        self.bus = smbus.SMBus(self.bus_number)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        close_bus(self.bus)

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None

    def probe(self):
        _probe_device(self.bus, self.address)

    def write_byte(self, register, value):
        _safe_write(self.bus, register, value)

    def read_byte(self, register):
        return _safe_read(self.bus, register)

    def close(self):
        self.close()


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with I2C_Device(I2C_ADDRESS, I2C_BUS_NUMBER) as device:
            print(f"Device at 0x{I2C_ADDRESS:02X} probed successfully.")
            print(f"Value written to register 0x{device.address:02X}: {device.write_byte(device.address, 0x00)}")
            print(f"Value read from register 0x{device.address:02X}: {device.read_byte(device.address)}")
    except RuntimeError as exc:
        print(f"Error: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        close_bus(device.bus)


if __name__ == "__main__":
    main()

