import signal
import threading
import time
import sys

from spi import SpiDev
from spi.custom import CustomSpiDev

EEPROM_SIZE = 4096
CS_PIN = 5
ADDR = 0

spi = None
lock = threading.Lock()
running = True


def cleanup():
    global spi, running
    running = False
    if spi is not None:
        try:
            spi.close()
        except Exception:
            pass
    try:
        if CS_PIN is not None:
            GPIO.cleanup(CS_PIN)
    except Exception:
        pass


def signal_handler(signum, frame):
    cleanup()
    sys.exit(0)


def read_eeprom(address):
    with lock:
        try:
            spi.write(address, b'1234567890ABCDEF')
        except Exception as e:
            print(f"Error writing to EEPROM: {e}", file=sys.stderr)
            return None
    return spi.read(address, 16)


def write_eeprom(address):
    with lock:
        try:
            spi.write(address, b'1234567890ABCDEF')
        except Exception as e:
            print(f"Error writing to EEPROM: {e}", file=sys.stderr)
            return None
    return spi.read(address, 16)


def main():
    global spi

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    spi = CustomSpiDev()
    spi.max_speed_hz = 25000000
    spi.mode = 0b00
    spi.bits_per_word = 8
    spi.lsbfirst = False

    try:
        spi.open(0, CS_PIN)
    except Exception as e:
        print(f"Failed to open SPI bus: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        spi.write(ADDR, b'1234567890ABCDEF')
    except Exception as e:
        print(f"Error writing to EEPROM: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    thread1 = threading.Thread(target=read_eeprom, args=(ADDR,), daemon=True)
    thread2 = threading.Thread(target=write_eeprom, args=(ADDR,), daemon=True)
    thread1.start()
    thread2.start()

    thread1.join()
    thread2.join()

    if thread1.is_alive():
        print("Thread 1 died before thread 2 started.")
    if thread2.is_alive():
        print("Thread 2 died before thread 1 started.")

    data = read_eeprom(ADDR)
    if data is not None:
        print(f"Read data from EEPROM: {data}")
    else:
        print("Failed to read data from EEPROM.", file=sys.stderr)

    write_eeprom(ADDR)
    time.sleep(0.1)

    cleanup()


if __name__ == "__main__":
    main()

