import serial
import time
import signal
import sys

# Constants for ESP8266 UART communication
ESP8266_PORT = '/dev/serial0'
ESP8266_BAUD = 115200
ESP8266_TIMEOUT = 1.0
ESP8266_REBOOT_TIMEOUT = 2.0
ESP8266_REBOOT_DELAY = 0.5

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def _send_command(uart, command):
    """
    Sends an AT command to the ESP8266 and returns the raw response.
    Raises serial.SerialException on failure.
    """
    try:
        uart.write(command + b'\r\n')
        uart.flush()
        response = uart.readline()
        if not response:
            raise serial.SerialException("No response received")
        return response.decode('utf-8', errors='replace').strip()
    except serial.SerialException as e:
        raise serial.SerialException(f"Error sending command: {e}")


def _wait_for_response(uart, timeout=ESP8266_TIMEOUT):
    """
    Waits for a response from the ESP8266 with a timeout.
    Returns the response string or None if no response is received within the timeout.
    """
    start_time = time.time()
    while time.time() - start_time < timeout:
        try:
            response = uart.readline()
            if response:
                return response.decode('utf-8', errors='replace')
        except serial.SerialException:
            return None
        except Exception as e:
            print(f"Error reading response: {e}")
            return None
    return None


def _send_command_with_timeout(uart, command, timeout=ESP8266_TIMEOUT):
    """
    Sends an AT command to the ESP8266 with a timeout.
    Returns the raw response or None on timeout.
    """
    try:
        response = _send_command(uart, command)
        return response
    except serial.SerialException as e:
        print(f"Error sending command: {e}")
        return None


def _wait_for_link(uart, timeout=ESP8266_TIMEOUT):
    """
    Waits for the ESP8266 to establish a link with a timeout.
    Returns True if a link is detected, False otherwise.
    """
    start_time = time.time()
    while time.time() - start_time < timeout:
        try:
            response = _wait_for_response(uart)
            if response and response.startswith('+IPD'):
                return True
        except Exception as e:
            print(f"Error waiting for link: {e}")
            return False
        except serial.SerialException:
            return False
        except Exception as e:
            print(f"Error waiting for link: {e}")
            return False
    return False


def _wait_for_reboot(uart, timeout=ESP8266_REBOOT_TIMEOUT):
    """
    Waits for the ESP8266 to reboot after a reset.
    Returns True if a reboot is detected, False otherwise.
    """
    start_time = time.time()
    while time.time() - start_time < timeout:
        try:
            response = _wait_for_response(uart)
            if response and response.startswith('ready'):
                return True
        except Exception as e:
            print(f"Error waiting for reboot: {e}")
            return False
        except serial.SerialException:
            return False
        except Exception as e:
            print(f"Error waiting for reboot: {e}")
            return False
    return False


def _reboot_esp8266(uart):
    """
    Restarts the ESP8266 by sending a reset command.
    """
    try:
        _send_command_with_timeout(uart, 'AT+RST')
        time.sleep(ESP8266_REBOOT_DELAY)
        return True
    except serial.SerialException as e:
        print(f"Error rebooting ESP8266: {e}")
        return False


def _get_ip_address(uart):
    """
    Gets the IP address of the ESP8266.
    """
    try:
        response = _send_command_with_timeout(uart, 'AT+CIFSR')
        if not response:
            return None
        parts = response.split(':')
        if len(parts) < 2:
            return None
        return parts[1]
    except serial.SerialException as e:
        print(f"Error getting IP address: {e}")
        return None


def _send_http_request(uart, method, url, host='www.google.com', port=80, headers=None, data=None):
    """
    Sends an HTTP request to the ESP8266 and returns the response.
    """
    try:
        if method == 'GET':
            command = 'AT+CIPSTART="TCP",'
        elif method == 'POST':
            command = 'AT+CIPSTART="TCP",'
        else:
            command = 'AT+CIPSTART="TCP",'
        command += f'{host}:{port}'
        command += ','
        command += 'AT+CIPSEND'
        _send_command_with_timeout(uart, command)
        if headers:
            for header in headers:
                _send_command_with_timeout(uart, f'AT+CPSENDHEADER "{header}"')
        if data:
            _send_command_with_timeout(uart, f'AT+CPSEND "{data}"')
        response = _send_command_with_timeout(uart, 'AT+CIPCLOSE')
        return response
    except serial.SerialException as e:
        print(f"Error sending HTTP request: {e}")
        return None
    except Exception as e:
        print(f"Error sending HTTP request: {e}")
        return None


