    """
    try:
        response = _send_http_request(uart, 'GET', 'http://www.google.com', headers={'User-Agent': 'ESP8266'})
        if response:
            parts = response.split(':')
            if len(parts) < 2:
                return None
            status_code = int(parts[1])
            if status_code == 200:
                return response.split('\r\n\r\n')[1]
            elif status_code == 404:
                return None
            else:
                return None
        return None
    except Exception as e:
        print(f"Error receiving HTTP response: {e}")
        return None


def connect_wifi(ssid, password):
