import time
import signal
import sys
import serial
import logging
from datetime import datetime

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

UART_PORT = "/dev/ttyUSB0"
UART_BAUDRATE = 9600
UART_TIMEOUT = 1
LOG_FILE = "health_readings_log.txt"
RETRY_DELAY = 5

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Received signal %d, shutting down...", sig)

def parse_hr_spo2(raw_data):
    try:
        parts = raw_data.split(',')
        if len(parts) != 2:
            raise ValueError("Expected 2 fields, got %d" % len(parts))
        hr = int(parts[0].strip())
        spo2 = int(parts[1].strip())
        return hr, spo2
    except ValueError:
        logging.error("Invalid data format: %s", raw_data)
        return None, None

def log_data(hr, spo2):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - Heart Rate: {hr} bpm, SpO2: {spo2} %\n"
    try:
        with open(LOG_FILE, "a") as f:
            f.write(log_entry)
    except IOError as e:
        logging.error("Failed to write to log file: %s", e)

def main():
    global running
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        with serial.Serial(UART_PORT, UART_BAUDRATE, timeout=UART_TIMEOUT) as ser:
            logging.info("Connected to %s at %d baud. Reading every %d seconds...", UART_PORT, UART_BAUDRATE, RETRY_DELAY)
            while running:
                try:
                    raw = ser.readline()
                    if not raw:
                        continue
                    hr, spo2 = parse_hr_spo2(raw.decode("ascii", errors="replace").strip())
                    if hr is not None and spo2 is not None:
                        log_data(hr, spo2)
                except serial.SerialException as e:
                    logging.error("Serial communication error: %s", e)
                    time.sleep(RETRY_DELAY)
                except ValueError as e:
                    logging.error("Invalid data format: %s", e)
                    time.sleep(RETRY_DELAY)
                except IOError as e:
                    logging.error("I/O error: %s", e)
                    time.sleep(RETRY_DELAY)
                except Exception as e:
                    logging.error("Unexpected error: %s", e)
                    time.sleep(RETRY_DELAY)
    except serial.SerialException as e:
        logging.error("Failed to open UART port %s: %s", UART_PORT, e)
        sys.exit(1)
    except Exception as e:
        logging.error("Initialization error: %s", e)
        sys.exit(1)
    finally:
        try:
            ser.close()
            logging.info("UART port closed.")
        except Exception as e:
            logging.error("Error closing UART port: %s", e)

if __name__ == "__main__":
    main()

