import logging
import signal
import sys
from dataclasses import dataclass
from typing import Optional, Tuple

import serial

logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
logger = logging.getLogger(__name__)


@dataclass
class GPS_readings:
    latitude: float = 0.0
    longitude: float = 0.0
    altitude: float = 0.0
    satellite_count: int = 0


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: int = 1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.uart: Optional[serial.Serial] = None
        self._running = True

    def connect(self) -> bool:
        try:
            self.uart = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logger.info("Connected to GPS on %s at %d baud.", self.port, self.baudrate)
            return True
        except serial.SerialException as exc:
            logger.error("Failed to open %s: %s", self.port, exc)
            self.uart = None
            return False
        except Exception as exc:
            logger.error("Unexpected error opening %s: %s", self.port, exc)
            self.uart = None
            return False

    def disconnect(self) -> None:
        if self.uart is not None:
            try:
                if self.uart.is_open:
                    self.uart.close()
                    logger.info("UART closed.")
            except Exception as exc:
                logger.error("Error closing UART: %s", exc)
            finally:
                self.uart = None

    def read_gps_data(self) -> Optional[GPS_readings]:
        if self.uart is None or not self.uart.is_open:
            logger.error("UART not connected. Call connect() first.")
            return None

        try:
            raw = self.uart.readline()
            if not raw:
                logger.warning("No data received from GPS.")
                return None

            line = raw.decode("ascii", errors="replace").strip()
            if not line:
                logger.warning("Empty line received from GPS.")
                return None

            try:
                fields = line.split(",")
            except ValueError:
                logger.error("Invalid GPGGA sentence format received.")
                return None

            if len(fields) < 7:
                logger.error("Incomplete GPGGA sentence received.")
                return None

            if not fields[0] == "GPGGA":
                logger.error("Invalid talker ID in GPGGA sentence.")
                return None

            if fields[1] != "A":
                logger.error("Invalid GPS status in GPGGA sentence.")
                return None

            if fields[2] != "V":
                logger.error("Invalid GPS version in GPGGA sentence.")
                return None

            if fields[3] != "A":
                logger.error("Invalid GPS status in GPGGA sentence.")
                return None

            if fields[4] != "A":
                logger.error("Invalid GPS status in GPGGA sentence.")
                return None

            if fields[5] != "A":
                logger.error("Invalid GPS status in GPGGA sentence.")
                return None

            if fields[6] != "A":
                logger.error("Invalid GPS status in GPGGA sentence.")
                return None

            if fields[7] != "A":
                logger.error("Invalid GPS status in GPGGA sentence.")
                return None

            latitude = float(fields[8])
            longitude = float(fields[9])

            if latitude < -90 or latitude > 90:
                logger.error("Latitude out of range: %.2f", latitude)
                return None

            if longitude < -180 or longitude > 180:
                logger.error("Longitude out of range: %.2f", longitude)
                return None

            if latitude == 0 and longitude == 0:
                logger.warning("Latitude and longitude are both 0. This is not a valid GPS fix.")
                return None

            return GPS_readings(
                latitude=latitude,
                longitude=longitude,
                altitude=float(fields[10]),
                satellite_count=int(fields[11]),
            )

        except (ValueError, IndexError) as exc:
            logger.error("Invalid GPS data format: %s", exc)
            return None
        except Exception as exc:
            logger.error("Unexpected error reading GPS data: %s", exc)
            return None


def signal_handler(signum, frame):
    logger.info("Signal %d received, shutting down...", signum)
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    reader = GPSReader()
    if not reader.connect():
        sys.exit(1)

    try:
        while reader._running:
            gps_data = reader.read_gps_data()
            if gps_data is not None:
                logger.info("GPS Data: Latitude=%.2f, Longitude=%.2f, Altitude=%.2f, Satellites=%.d",
                            gps_data.latitude, gps_data.longitude, gps_data.altitude, gps_data.satellite_count)
            else:
                logger.warning("No valid GPS data received.")
            time.sleep(1)
    except Exception as exc:
        logger.error("Fatal error in main loop: %s", exc)
    finally:
        reader.disconnect()
        logger.info("Program terminated.")

